const rows = name => { try { return $(name).all().map(item => item.json); } catch (error) { return []; } };
const clients = rows('Read Clients');
const compliance = rows('Read Compliance');
const documents = rows('Read Documents');
const leads = rows('Read Leads');
const invoices = rows('Read Invoices');
const number = value => Number(String(value ?? 0).replace(/[^0-9.-]/g, '')) || 0;
const isOpen = value => !['paid', 'closed', 'completed', 'done', 'received', 'cold-closed'].includes(String(value || '').toLowerCase());
const today = new Date();
const daysUntil = value => { const date = new Date(value); return Number.isNaN(date.getTime()) ? 9999 : Math.ceil((date - today) / 86400000); };
const pendingCompliance = compliance.filter(row => isOpen(row.status));
const urgentCompliance = pendingCompliance.filter(row => daysUntil(row.due_date) <= 7).length;
const pendingInvoices = invoices.filter(row => isOpen(row.status));
const collected = invoices.filter(row => String(row.status || '').toLowerCase() === 'paid').reduce((sum, row) => sum + number(row.amount), 0);
const outstanding = pendingInvoices.reduce((sum, row) => sum + number(row.amount), 0);
const overdueClients = pendingInvoices.filter(row => daysUntil(row.due_date) < 0).length;
const tasks = [
  ...pendingCompliance.map(row => ({ id: row.compliance_id, title: row.compliance_type || 'Compliance filing', client: row.client_name, due_date: row.due_date, status: row.status || 'Pending', priority: daysUntil(row.due_date) <= 3 ? 'Urgent' : 'High', source: 'Compliance' })),
  ...documents.filter(row => isOpen(row.status)).map(row => ({ id: row.doc_id, title: `Collect ${row.document_name || 'document'}`, client: row.client_name, due_date: row.requested_date, status: row.status || 'Pending', priority: 'Medium', source: 'Documents' })),
  ...pendingInvoices.filter(row => daysUntil(row.due_date) < 0).map(row => ({ id: row.invoice_id, title: `Follow up invoice ${row.invoice_id}`, client: row.client_name, due_date: row.due_date, status: row.status || 'Overdue', priority: 'Urgent', source: 'Invoices' }))
].slice(0, 100);
return [{ json: { clients: { total: clients.length, rows: clients, change: 'Live from Clients sheet' }, deadlines: { pending: pendingCompliance.length, urgent: urgentCompliance, rows: pendingCompliance }, invoices: { collected: `₹${(collected / 100000).toFixed(1)}L`, pending: `₹${(outstanding / 100000).toFixed(1)}L`, overdueClients, rows: invoices, change: 'Live from Invoices sheet' }, documents: { pending: documents.filter(row => isOpen(row.status)).length, rows: documents }, leads: { active: leads.filter(row => isOpen(row.status)).length, rows: leads }, tasks, reports: { complianceRate: compliance.length ? Math.round((compliance.filter(row => String(row.status || '').toLowerCase() === 'completed').length / compliance.length) * 100) : 0, automationHours: Math.round((documents.length + leads.length + compliance.length) * 0.25) }, generated_at: new Date().toISOString() } }];
